ALTER TABLE "local_backup_evidence" DROP CONSTRAINT "local_backup_evidence_pass_valid";--> statement-breakpoint
ALTER TABLE "local_backup_evidence" ADD CONSTRAINT "local_backup_evidence_pass_valid" CHECK ("local_backup_evidence"."outcome" <> 'passed' or ("local_backup_evidence"."archive_sha256" is not null and "local_backup_evidence"."archive_sha256" ~ '^[0-9a-f]{64}$' and "local_backup_evidence"."archive_bytes" > 0 and "local_backup_evidence"."source_schema_table_count" > 0 and "local_backup_evidence"."source_schema_table_count" = "local_backup_evidence"."restored_schema_table_count" and "local_backup_evidence"."error_code" is null and (("local_backup_evidence"."capture_id" is null and "local_backup_evidence"."source_capture_sha256" is null and "local_backup_evidence"."restored_capture_sha256" is null) or ("local_backup_evidence"."capture_id" is not null and "local_backup_evidence"."source_capture_sha256" is not null and "local_backup_evidence"."restored_capture_sha256" is not null and "local_backup_evidence"."source_capture_sha256" ~ '^[0-9a-f]{64}$' and "local_backup_evidence"."source_capture_sha256" = "local_backup_evidence"."restored_capture_sha256"))));